"""Build README.md for my GitHub profile.

Run make_gifs.py first, then: uv run build_readme.py
"""

# /// script
# requires-python = ">=3.10"
# dependencies = ["hubbub @ git+https://github.com/mjfrigaard/hubbub"]
# ///

from pathlib import Path

from hubbub import gh_badges, so_rep  # noqa: F401

# the interactive version lives in the hubbub docs
SPIRAL_URL = (
    "https://mjfrigaard.github.io/hubbub/user-guide/walkthrough.html"
    "#interactive-spiral"
)

sections = [
    "# Hi there \U0001f44b",
    "<!-- README.md is generated by build_readme.py. Please edit that file. -->",
    "![](who_am_i.gif)",
    "## GitHub activity",
    "![Cumulative commits](cumulative.gif)",
    f"[![Commit spiral (click for the interactive version)](spiral.png)]({SPIRAL_URL})",
    gh_badges(
        username="mjfrigaard",
        badge=["details", "stats", "repo_lang"],
        theme="dark",
    ),
]

# Optional: Stack Overflow reputation badge.
# sections.append(so_rep(username="martin-frigaard", user_id="4926446"))

Path("README.md").write_text("\n\n".join(sections) + "\n", encoding="utf-8")
print("Wrote README.md")
